package com.cpf.starter.soap;import java.util.function.Supplier;import org.springframework.ws.WebServiceMessage;import org.springframework.ws.client.WebServiceIOException;import org.springframework.ws.client.core.WebServiceTemplate;import org.springframework.ws.soap.SoapMessage;public final class CpfSoapClient {private final WebServiceTemplate template;private final CpfSoapProperties p;public CpfSoapClient(WebServiceTemplate t,CpfSoapProperties p){template=t;this.p=p;}public Object call(Object request){try{return template.marshalSendAndReceive(p.getEndpoint(),request,m->{if(m instanceof SoapMessage s&&p.getAction()!=null)s.setSoapAction(p.getAction());});}catch(WebServiceIOException ex){throw new UnknownResultException("SOAP response result unknown; reconcile before retry",ex);}catch(RuntimeException ex){throw new SoapFaultException("SOAP fault/contract failure",ex);}}public static final class UnknownResultException extends RuntimeException{public UnknownResultException(String m,Throwable c){super(m,c);}}public static final class SoapFaultException extends RuntimeException{public SoapFaultException(String m,Throwable c){super(m,c);}}}
